const rotateSession = `-- name: RotateSession :execrows
UPDATE sessions
SET token_hash = $1, last_seen_at = $2, expires_at = $3
WHERE token_hash = $4 AND expires_at > now() AND max_expires_at > now()
`

type RotateSessionParams struct {
	NewTokenHash []byte
	LastSeenAt   time.Time
	ExpiresAt    time.Time
	OldTokenHash []byte
}

// Each refresh replaces the token: a used token stops working, so a stolen copy is good for one use at most.
func (q *Queries) RotateSession(ctx context.Context, arg RotateSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, rotateSession,
		arg.NewTokenHash,
		arg.LastSeenAt,
		arg.ExpiresAt,
		arg.OldTokenHash,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

